// Node tests for the pure results module (src/results.ts — docs/08 R25): the
// simulation log, the run verdict, the attribution of a report to an element of
// the verification view, imc's coverage summary, and the folded snapshot.
//
// The fixtures under scripts/fixtures/results/ are REAL: the yapp_buffer
// tutorial bench generated by quick-uvm 1.1.0 and run with `make regress` on
// Xcelium 25.09 (paths sanitised) — `fatal/` with the generated predictor stub
// still in place, `errors/` with a deliberately wrong prediction.
//   npm run test:results
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import esbuild from "esbuild";

const outDir = mkdtempSync(join(tmpdir(), "quickuvm-results-"));
const outFile = join(outDir, "results.mjs");
await esbuild.build({
  entryPoints: ["src/results.ts"],
  outfile: outFile,
  bundle: true,
  format: "esm",
  platform: "node",
  logLevel: "silent",
});
const R = await import(pathToFileURL(outFile));

let passed = 0;
function test(name, fn) {
  fn();
  passed += 1;
  console.log(`  ok ${name}`);
}
const fx = (...p) => readFileSync(join("scripts/fixtures/results", ...p), "utf8");
const run = (set, dir) =>
  R.runResult(dir, {
    status: fx(set, "runs", dir, "status"),
    test: fx(set, "runs", dir, "test.txt"),
    seed: fx(set, "runs", dir, "seed.txt"),
    log: fx(set, "runs", dir, "sim.log"),
  });
const NAMES = { agents: ["cmd", "rsp"], scoreboards: ["pkt_sb"], subenvs: [] };

test("log (real, fatal): one UVM_FATAL from the predictor, the server's counts, $finish", () => {
  const log = R.parseSimLog(fx("fatal", "runs", "yapp_buffer_test.1", "sim.log"));
  assert.deepEqual(log.counts, { info: 3, warning: 0, error: 0, fatal: 1 });
  assert.equal(log.finished, true);
  assert.equal(log.reports.length, 1, "the INFOs are counted, not kept");
  const r = log.reports[0];
  assert.equal(r.severity, "fatal");
  assert.equal(r.file, "../tb/yapp_buffer_reference_model.svh");
  assert.equal(r.line, 43);
  assert.equal(r.time, 65);
  assert.equal(r.path, "uvm_test_top.e.pkt_sb.prd");
  assert.equal(r.id, "UNFILLED_PREDICTOR");
  assert.ok(r.message.startsWith("the `prediction_logic` seam is still the generated stub"));
});

test("log (real, errors): 102 errors and a warning, all from the comparator; the catcher's zeros are not read", () => {
  const text = fx("errors", "runs", "yapp_buffer_test.1", "sim.log");
  const log = R.parseSimLog(text);
  assert.deepEqual(log.counts, { info: 4, warning: 1, error: 102, fatal: 0 });
  assert.equal(log.reports.filter((r) => r.severity === "error").length, 102, "every error line is parsed");
  assert.equal(log.reports.filter((r) => r.severity === "warning").length, 1);
  assert.deepEqual([...new Set(log.reports.map((r) => r.path))], ["uvm_test_top.e.pkt_sb.cmp"]);
  assert.deepEqual([...new Set(log.reports.map((r) => r.id))].sort(), ["ERROR", "FAILED", "SB_LEFTOVER", "SB_NOEXP"]);
  // the report CATCHER prints "Number of caught UVM_ERROR reports : 0" on this
  // failing run — a parser that read it would call the run clean
  assert.ok(text.includes("Number of caught UVM_ERROR reports   :    0"));
  assert.equal(R.verdictOf(log), "FAIL");
});

test("verdict: the Makefile's rule — $finish AND no error AND no fatal; no summary is a FAIL", () => {
  const ok = "UVM_INFO @ 0: reporter [RNTST] Running test t...\n** Report counts by severity\nUVM_INFO :    3\nUVM_WARNING :    2\nUVM_ERROR :    0\nUVM_FATAL :    0\n** Report counts by id\n[RNTST]     1\n\nSimulation complete via $finish(1) at time 65 NS + 3\n";
  assert.equal(R.verdictOf(R.parseSimLog(ok)), "PASS", "warnings do not fail a run");
  assert.equal(R.verdictOf(R.parseSimLog(ok.replace("UVM_ERROR :    0", "UVM_ERROR :    1"))), "FAIL");
  assert.equal(R.verdictOf(R.parseSimLog(ok.replace(/Simulation complete.*\n/, ""))), "FAIL", "never reached $finish");
  assert.equal(R.verdictOf(R.parseSimLog("xmsim: *F,NOSNAP: snapshot not found\n")), "FAIL", "a crash has no summary");
  assert.equal(R.verdictOf(R.parseSimLog("")), "FAIL");
  // "[ERROR]    70" in the by-id block is an ID count, not the severity block
  const ids = R.parseSimLog(ok.replace("[RNTST]     1", "[ERROR]    70"));
  assert.equal(ids.counts.error, 0);
});

test("report lines: with and without a file, a time unit, CRLF, a message with brackets", () => {
  const log = R.parseSimLog(
    [
      "UVM_ERROR @ 120: reporter [TIMEOUT] no file here",
      "UVM_WARNING /a b/c.svh(7) @ 15 ns: uvm_test_top.e.cmd_agnt.mon [X/Y] got [3] items\r",
      "UVM_ERROR : this is not a report",
      "  UVM_ERROR ../tb/x.svh(1) @ 5: uvm_test_top [INDENTED] not at the line start",
      "UVM_INFO ../tb/x.svh(1) @ 5: uvm_test_top [I] skipped",
    ].join("\n")
  );
  assert.deepEqual(log.reports, [
    { severity: "error", file: null, line: null, time: 120, path: "reporter", id: "TIMEOUT", message: "no file here" },
    { severity: "warning", file: "/a b/c.svh", line: 7, time: 15, path: "uvm_test_top.e.cmd_agnt.mon", id: "X/Y", message: "got [3] items" },
  ]);
});

test("run: the status file is the verdict; without it the log decides; with neither it is UNKNOWN", () => {
  const r = run("errors", "yapp_buffer_test.1");
  assert.deepEqual([r.test, r.seed, r.status], ["yapp_buffer_test", "1", "FAIL"]);
  assert.deepEqual(r.counts, { info: 4, warning: 1, error: 102, fatal: 0 });
  // test and seed fall back to the directory name
  const bare = R.runResult("my.test.7", {});
  assert.deepEqual([bare.test, bare.seed, bare.status], ["my.test", "7", "UNKNOWN"]);
  // no status: the log's verdict; a status wins over the log
  const log = fx("fatal", "runs", "yapp_buffer_test.1", "sim.log");
  assert.equal(R.runResult("t.1", { log }).status, "FAIL");
  assert.equal(R.runResult("t.1", { log, status: "pass\n" }).status, "PASS", "the Makefile's file is authoritative");
  assert.equal(R.runResult("t.1", { status: "garbage" }).status, "UNKNOWN");
  // a log cut before the summary: the counts are what was parsed
  const cut = R.runResult("t.1", { log: "UVM_ERROR @ 1: uvm_test_top.e.pkt_sb [A] x\n" });
  assert.deepEqual(cut.counts, { info: 0, warning: 0, error: 1, fatal: 0 });
});

test("attribution: a path names its element by the generator's instance names", () => {
  const at = (p) => R.elementOfPath(p, NAMES);
  assert.deepEqual(at("uvm_test_top.e.pkt_sb.cmp"), { id: "sb:pkt_sb", unit: null });
  assert.deepEqual(at("uvm_test_top.e.pkt_sb"), { id: "sb:pkt_sb", unit: null });
  assert.deepEqual(at("uvm_test_top.e.cmd_agnt.mon"), { id: "agent:cmd", unit: "u.monitor" });
  assert.deepEqual(at("uvm_test_top.e.rsp_agnt.drv"), { id: "agent:rsp", unit: "u.driver" });
  assert.deepEqual(at("uvm_test_top.e.cmd_agnt.sqr.seq"), { id: "agent:cmd", unit: "u.sequencer" });
  assert.deepEqual(at("uvm_test_top.e.cmd_agnt"), { id: "agent:cmd", unit: null });
  assert.deepEqual(at("uvm_test_top.e.cmd_cov_h"), { id: "cov:cmd", unit: null });
  assert.deepEqual(at("uvm_test_top.e.vsqr"), { id: "vsqr", unit: null });
  assert.deepEqual(at("uvm_test_top.e"), { id: "env", unit: null });
  assert.deepEqual(at("uvm_test_top"), { id: "env", unit: null });
  assert.deepEqual(at("uvm_test_top.e.something_else.x"), { id: "env", unit: null }, "under the env, not drawn: the env");
  assert.equal(at("reporter"), null, "not under the test: the caller decides");
  // the env's instance name is a position, not a name
  assert.deepEqual(R.elementOfPath("uvm_test_top.my_env.pkt_sb", NAMES), { id: "sb:pkt_sb", unit: null });
  // an agent the config does not have is not invented
  assert.deepEqual(at("uvm_test_top.e.ghost_agnt.mon"), { id: "env", unit: null });
  // a composed block
  assert.deepEqual(
    R.elementOfPath("uvm_test_top.e.ch0.chan_a_agnt.mon", { agents: [], scoreboards: [], subenvs: ["ch0"] }),
    { id: "sub:ch0", unit: null }
  );
  // an agent NAMED like another's suffix does not swallow it
  const tricky = { agents: ["a", "a_cov_h"], scoreboards: [], subenvs: [] };
  assert.deepEqual(R.elementOfPath("uvm_test_top.e.a_cov_h_agnt", tricky), { id: "agent:a_cov_h", unit: null });
  assert.deepEqual(R.elementOfPath("uvm_test_top.e.a_cov_h", tricky), { id: "cov:a", unit: null });
});

test("coverage (real imc summary): the tree, the columns with a space in their name, n/a absent", () => {
  const rows = R.parseImcSummary(fx("errors", "cov", "summary.txt"));
  assert.deepEqual(rows.map((r) => r.path.join(".")), [
    "uvm_pkg",
    "uvm_pkg.uvm_test_top",
    "uvm_pkg.uvm_test_top.e",
    "uvm_pkg.uvm_test_top.e.cmd_cov_h",
    "tb_top",
    "tb_top.ck",
    "tb_top.cmd_if_inst",
    "tb_top.rsp_if_inst",
    "tb_top.dut_inst",
  ]);
  const cov = rows.find((r) => r.path.at(-1) === "cmd_cov_h");
  assert.deepEqual(cov.metrics, {
    "CoverGroup Average": { pct: 100, covered: null, total: null },
    "CoverGroup Covered": { pct: 100, covered: 16, total: 16 },
  });
  const dut = rows.find((r) => r.path.at(-1) === "dut_inst");
  assert.deepEqual(dut.metrics.Block, { pct: 100, covered: 7, total: 7 });
  assert.ok(dut.metrics.Expression && dut.metrics.Toggle);
  assert.equal("Statement" in dut.metrics, false, "n/a is not a figure");
  assert.deepEqual(rows[0].metrics, {});
  // the other real run: a collector that covered nothing
  const zero = R.parseImcSummary(fx("fatal", "cov", "summary.txt")).find((r) => r.path.at(-1) === "cmd_cov_h");
  assert.deepEqual(zero.metrics["CoverGroup Covered"], { pct: 0, covered: 0, total: 16 });
  assert.deepEqual(R.parseImcSummary(""), []);
  assert.deepEqual(R.parseImcSummary("imc: *E,NOLIC: no licence\n"), [], "not a table: nothing, not a throw");
});

test("snapshot (real, errors): the scoreboard carries the errors, folded by id; coverage on its boxes", () => {
  const runs = [run("errors", "yapp_buffer_test.1"), run("errors", "smoke_test.1")];
  const s = R.summarizeResults(runs, R.parseImcSummary(fx("errors", "cov", "summary.txt")), NAMES);
  assert.deepEqual(s.runs.map((r) => `${r.test}.${r.seed}:${r.status}`), ["yapp_buffer_test.1:FAIL", "smoke_test.1:FAIL"]);
  assert.deepEqual([s.passed, s.failed], [0, 2]);
  assert.deepEqual(Object.keys(s.elements), ["sb:pkt_sb"], "everything was raised by the comparator");
  const sb = s.elements["sb:pkt_sb"];
  assert.equal(sb.fatals, 0);
  assert.equal(sb.errors, runs[0].counts.error + runs[1].counts.error);
  assert.equal(sb.warnings, runs[0].counts.warning + runs[1].counts.warning);
  // hundreds of reports, a handful of messages: same severity + id + line fold
  assert.ok(sb.messages.length <= 8);
  const mismatch = sb.messages.find((m) => m.id === "ERROR");
  assert.ok(mismatch.count >= 70, "the per-transaction mismatches are one line with a count");
  assert.ok(mismatch.message.startsWith("Expected:"));
  assert.equal(mismatch.file, "../tb/yapp_buffer_comparator.svh");
  assert.equal(mismatch.run, "yapp_buffer_test.1");
  assert.equal(sb.messages.reduce((n, m) => n + m.count, 0), sb.errors + sb.warnings, "nothing is lost in the fold");
  assert.deepEqual(s.coverage["cov:cmd"], [{ label: "cg", pct: 100, covered: 16, total: 16 }]);
  assert.deepEqual(s.coverage.dut.map((f) => f.label), ["block", "expr", "toggle"]);
  assert.equal(R.worstOf(sb), "error");
});

test("snapshot (real, fatal): the fatal lands on the scoreboard whose predictor raised it", () => {
  const s = R.summarizeResults([run("fatal", "yapp_buffer_test.1")], [], NAMES);
  assert.deepEqual(s.elements["sb:pkt_sb"], {
    fatals: 1, errors: 0, warnings: 0,
    messages: [{
      severity: "fatal", id: "UNFILLED_PREDICTOR", count: 1,
      message: s.elements["sb:pkt_sb"].messages[0].message,
      file: "../tb/yapp_buffer_reference_model.svh", line: 43, run: "yapp_buffer_test.1",
    }],
  });
  assert.equal(R.worstOf(s.elements["sb:pkt_sb"]), "fatal");
  assert.deepEqual(s.coverage, {});
  assert.equal(R.worstOf(undefined), null);
});

test("snapshot: a unit is counted on its agent AND under its own key; a report is never dropped", () => {
  const mk = (path, file = null) => ({ severity: "error", file, line: 1, time: 1, path, id: "X", message: "m" });
  const runs = [{
    test: "t", seed: "1", status: "FAIL", counts: { info: 0, warning: 0, error: 4, fatal: 0 },
    reports: [
      mk("uvm_test_top.e.cmd_agnt.mon"),
      mk("uvm_test_top.e.cmd_agnt.drv"),
      mk("reporter", "../tb/rsp_monitor.svh"),
      mk("reporter", "../tb/unknown.svh"),
    ],
  }];
  const owner = (f) => (f.endsWith("rsp_monitor.svh") ? "agent:rsp" : null);
  const s = R.summarizeResults(runs, [], NAMES, owner);
  assert.equal(s.elements["agent:cmd"].errors, 2);
  assert.equal(s.elements["agent:cmd:u.monitor"].errors, 1);
  assert.equal(s.elements["agent:cmd:u.driver"].errors, 1);
  assert.equal(s.elements["agent:rsp"].errors, 1, "not under the test: the owner of its source file");
  assert.equal(s.elements.env.errors, 1, "nobody owns it: the env — never dropped");
  // without the manifest, both `reporter` lines go to the env
  assert.equal(R.summarizeResults(runs, [], NAMES).elements.env.errors, 2);
});

test("snapshot: coverage only on what the configuration has; no runs is an empty snapshot", () => {
  const rows = R.parseImcSummary(fx("errors", "cov", "summary.txt"));
  const none = R.summarizeResults([], rows, { agents: [], scoreboards: [], subenvs: [] });
  assert.equal("cov:cmd" in none.coverage, false, "an agent the config does not have gets no figure");
  assert.ok(none.coverage.dut);
  assert.deepEqual(R.summarizeResults([], [], NAMES), { runs: [], passed: 0, failed: 0, elements: {}, coverage: {} });
});

// ------------------------------------------------------ what a level shows
const SNAP = () => {
  const mk = (path, sev = "error") => ({ severity: sev, file: "../tb/f.svh", line: 3, time: 1, path, id: "X", message: "m" });
  return R.summarizeResults(
    [{
      test: "t", seed: "1", status: "FAIL", counts: { info: 0, warning: 1, error: 4, fatal: 0 },
      reports: [
        mk("uvm_test_top.e.cmd_agnt.mon"),
        mk("uvm_test_top.e.cmd_agnt.drv", "warning"),
        mk("uvm_test_top.e.pkt_sb.cmp"),
        mk("uvm_test_top.e"),
        mk("uvm_test_top.e.rsp_cov_h"),
      ],
    }],
    R.parseImcSummary(fx("errors", "cov", "summary.txt")),
    NAMES
  );
};

test("level: at the testbench level the env block carries everything inside it; coverage is not summed", () => {
  const n = R.levelResults(SNAP(), "", ["dut", "env"]);
  assert.deepEqual([n.env.fatals, n.env.errors, n.env.warnings], [0, 4, 1], "an error two levels down is still on screen");
  assert.deepEqual(n.env.coverage, [], "a figure belongs to one instance");
  assert.deepEqual(n.dut.coverage.map((f) => f.label), ["block", "expr", "toggle"]);
  assert.equal(n.dut.errors, 0);
  assert.equal(R.worstOfNode(n.env), "error");
  assert.equal(R.worstOfNode(n.dut), null);
});

test("level: at the env level each block shows its own; a unit is not counted twice", () => {
  const n = R.levelResults(SNAP(), "env", ["agent:cmd", "agent:rsp", "sb:pkt_sb", "cov:cmd", "cov:rsp", "vsqr"]);
  assert.deepEqual([n["agent:cmd"].errors, n["agent:cmd"].warnings], [1, 1], "the agent's total, units included ONCE");
  assert.equal(n["sb:pkt_sb"].errors, 1);
  assert.equal(n["cov:rsp"].errors, 1);
  assert.deepEqual(n["cov:cmd"].coverage, [{ label: "cg", pct: 100, covered: 16, total: 16 }]);
  assert.equal(n["agent:rsp"], undefined, "nothing reported: no entry, no badge");
  assert.equal(n.env, undefined, "the env's own report has no block on this level");
  assert.equal(Object.keys(n).some((k) => k.includes(":u.")), false);
});

test("level: at an agent's level its units; a cross-block scoreboard at the root; no snapshot, nothing", () => {
  const n = R.levelResults(SNAP(), "agent:cmd", ["u.sequencer", "u.driver", "u.monitor"]);
  assert.deepEqual(Object.keys(n).sort(), ["u.driver", "u.monitor"]);
  assert.equal(n["u.monitor"].errors, 1);
  assert.equal(n["u.driver"].warnings, 1);
  assert.deepEqual(R.levelResults(SNAP(), "agent:rsp", ["u.sequencer", "u.driver", "u.monitor"]), {},
    "another agent's units are not this level's");
  const x = R.levelResults(SNAP(), "", ["env", "xsb:pkt_sb"]);
  assert.equal(x["xsb:pkt_sb"].errors, 1, "the element's own block wins over the env");
  assert.equal(x.env.errors, 3);
  assert.deepEqual(R.levelResults(null, "env", ["agent:cmd"]), {});
});

test("chip: the VERDICTS of the runs, and that they are stale", () => {
  const s = (runs) => ({ runs, passed: runs.filter((r) => r.status === "PASS").length, failed: runs.filter((r) => r.status === "FAIL").length, elements: {}, coverage: {} });
  const r = (status) => ({ test: "t", seed: "1", status });
  assert.deepEqual(R.resultsChip(s([r("PASS"), r("PASS")]), false), { text: "Runs: 2 passed", tone: "pass" });
  assert.deepEqual(R.resultsChip(s([r("PASS"), r("FAIL"), r("FAIL")]), false), { text: "Runs: 1/3 passed", tone: "fail" });
  assert.deepEqual(R.resultsChip(s([r("PASS"), r("UNKNOWN")]), true), { text: "Runs: 1 passed, 1 without a verdict (stale)", tone: "unknown" });
});

test("report (real): runs, elements worst first with folded messages, coverage; stale and partial are SAID", () => {
  const runs = [run("errors", "yapp_buffer_test.1"), run("errors", "smoke_test.1")];
  const snapshot = R.summarizeResults(runs, R.parseImcSummary(fx("errors", "cov", "summary.txt")), NAMES);
  const text = R.resultsReport({ snapshot, dir: "/w/tb/out", at: Date.UTC(2026, 10, 21, 9, 30), unparsed: 0 }, { name: "yapp_buffer.quickuvm.yaml", stale: false });
  assert.match(text, /^# Simulation results — yapp_buffer\.quickuvm\.yaml/);
  assert.match(text, /2 runs: 0 passed, 2 failed — 2026-11-21 09:30 UTC/);
  assert.match(text, /\| yapp_buffer_test \| 1 \| FAIL \|/);
  assert.match(text, /### `sb:pkt_sb` — \d+ errors, \d+ warnings?/);
  assert.match(text, /- UVM_ERROR \[ERROR\] ×\d+ — Expected:.*\(yapp_buffer_comparator\.svh:\d+, yapp_buffer_test\.1\)/);
  assert.match(text, /- `cov:cmd`: cg 100% \(16\/16\)/);
  assert.doesNotMatch(text, /Stale|Partial/);
  const flagged = R.resultsReport({ snapshot, dir: "d", at: null, unparsed: 2 }, { name: "x", stale: true });
  assert.match(flagged, /\*\*Stale:\*\*/);
  assert.match(flagged, /\*\*Partial:\*\* 2 logs were not parsed/);
  const clean = R.resultsReport({ snapshot: R.summarizeResults([], [], NAMES), dir: "d", at: null, unparsed: 0 }, { name: "x", stale: false });
  assert.match(clean, /No warning, error or fatal was reported\./);
});

console.log(`\ntest-results: ${passed} tests passed.`);
